const items = $input.all();
if (items.length === 0) return [];

// Lấy ngày bắt đầu dự án hoặc mốc thời gian hiện tại
let currentDate = new Date(items[0].json.project_start_date || Date.now());

const results = [];

for (const item of items) {
  const data = item.json;
  const storyPoints = data.story_points || 1;
  const productivity = parseFloat(data.productivity_score) || 100;

  // Tính số ngày cần hoàn thành task (giả định 1 member làm được 2 points/ngày)
  const daysNeeded = Math.max(1, Math.ceil(storyPoints / ((productivity / 100) * 2)));

  // Tịnh tiến ngày due_date tiếp theo
  currentDate.setDate(currentDate.getDate() + daysNeeded);

  results.push({
    json: {
      task_id: data.task_id,
      title: data.title,
      calculated_days: daysNeeded,
      due_date: currentDate.toISOString()
    }
  });
}

return results;
